  "implementation": "def solve(case):
    # Extract fields
    initial = case['initial_state']
    max_steps = case['max_steps']
    tobs = case['tool_observations']
    trans = case['transitions']

    # Validate all states exist
    for state, info in trans.items():
        if info['kind'] == 'action':
            if info['action'] not in tobs:
                raise ValueError(f"Missing tool observation for action: {info['action']}")
            for obs in info['next_by_observation'].values():
                if obs not in trans:
                    raise ValueError(f"Transition target {obs} not in states")
            if info['default_next'] not in trans:
                raise ValueError(f"Default target {info['default_next']} not in states")
        elif info['kind'] == 'final':
            pass
        else:
            raise ValueError(f"Unknown state kind: {info['kind']}")
    if initial not in trans:
        raise ValueError("Initial state not in transitions")

    state = initial
    step = 0
    trace = []

    while True:
        # Check if current state is final
        node = trans[state]
        if node['kind'] == 'final':
            status = 'completed'
            final = node['value']
            return {'final': final, 'status': status, 'trace': trace}

        # Must be an action state
        if step >= max_steps:
            # Exceeded max steps without reaching final
            return {'final': None, 'status': 'max_steps_reached', 'trace': trace}

        # Execute action
        action = node['action']
        observation = tobs[action]
        step += 1

        # Determine next state
        next_state = node['next_by_observation'].get(observation, node['default_next'])

        # Record trace entry
        trace.append({
            'step': step,
            'action': action,
            'observation': observation,
            'state': next_state
        })

        # Move to next state
        state = next_state"
}
